// --- Stack Implementation ---

#include <stack>

// Function to reverse an array using two stacks
std::vector<int> reverseArray(const std::vector<int>& arr) {
    std::stack<int> stackA, stackB;
    std::vector<int> reversed;

    // Push all elements onto stack A
    for (int num : arr) {
        stackA.push(num);
    }

    // Pop elements into stack B in reverse order
    while (!stackA.empty()) {
        stackB.push(stackA.top());
        stackA.pop();
    }

    // Pop elements from stack B to get the reversed array
    while (!stackB.empty()) {
        reversed.push_back(stackB.top());
        stackB.pop();
    }

    return reversed;
}

