// --- build adjacency list ---
std::vector<std::vector<int>> build_adjacency_list(int n, std::vector<std::pair<int, int>>& edges) {
    std::vector<std::vector<int>> adj(n);
    for (const auto& [u, v] : edges) {
        adj[u].push_back(v);
        adj[v].push_back(u);
    }
    return adj;
}

// --- dynamic programming function ---
std::vector<int> dp(int n, std::vector<std::vector<int>>& adj) {
    std::vector<int> dist(n, INT_MAX);
    dist[0] = 0;
    std::queue<int> q;
    q.push(0);

    while (!q.empty()) {
        int u = q.front();
        q.pop();
        for (int v : adj[u]) {
            if (dist[v] > dist[u] + 1) {
                dist[v] = dist[u] + 1;
                q.push(v);
            }
        }
    }

    return dist;
}

// --- main function ---
std::vector<int> solve(int n, std::vector<std::pair<int, int>>& edges) {
    auto adj = build_adjacency_list(n, edges);
    return dp(n, adj);
}

