// --- Brute Force Two Sum ---

#include <vector>
#include <utility>
#include <algorithm>

// Function to find two numbers in an array that sum up to a target value
std::pair<int, int> twoSum(const std::vector<int>& nums, int target) {
    // Time: O(n^2) — Space: O(1)

    // Iterate through each element in the array
    for (size_t i = 0; i < nums.size(); ++i) {
        // For each element, check every other element
        for (size_t j = i + 1; j < nums.size(); ++j) {
            // If the sum of the current pair equals the target, return the indices
            if (nums[i] + nums[j] == target) {
                return {static_cast<int>(i), static_cast<int>(j)};
            }
        }
    }
    // If no solution is found, return a default value (e.g., {-1, -1})
    return {-1, -1};
}

