#include <iostream>

// Function to simulate population growth
long long simulatePopulationGrowth(long long initialPopulation, int years) {
    // --- Initialize variables ---
    long long currentPopulation = initialPopulation;

    // --- Simulate population growth for each year ---
    for (int year = 0; year < years; ++year) {
        currentPopulation *= 2; // Each year the population doubles
    }

    return currentPopulation;
}

