// --- build adjacency list ---
std::vector<std::vector<int>> build_adjacency_list(const std::vector<std::pair<int, int>>& edges, int num_nodes) {
    std::vector<std::vector<int>> adj(num_nodes);
    for (const auto& [u, v] : edges) {
        adj[u].push_back(v);
        adj[v].push_back(u); // For undirected graph
    }
    return adj;
}

// --- BFS traversal ---
std::vector<int> bfs(const std::vector<std::vector<int>>& adj, int start) {
    std::vector<bool> visited(adj.size(), false);
    std::queue<int> q;
    q.push(start);
    visited[start] = true;
    std::vector<int> result;

    while (!q.empty()) {
        int u = q.front();
        q.pop();
        result.push_back(u);

        for (int v : adj[u]) {
            if (!visited[v]) {
                visited[v] = true;
                q.push(v);
            }
        }
    }

    return result;
}

// --- DFS traversal ---
void dfs(const std::vector<std::vector<int>>& adj, int u, std::vector<bool>& visited, std::vector<int>& result) {
    visited[u] = true;
    result.push_back(u);

    for (int v : adj[u]) {
        if (!visited[v]) {
            dfs(adj, v, visited, result);
        }
    }
}

std::vector<int> dfs(const std::vector<std::vector<int>>& adj, int start) {
    std::vector<bool> visited(adj.size(), false);
    std::vector<int> result;
    dfs(adj, start, visited, result);
    return result;
}

