// --- Binary Search Tree Implementation ---

// Node structure for the BST
struct TreeNode {
    int key;
    TreeNode* left;
    TreeNode* right;
    TreeNode(int x) : key(x), left(nullptr), right(nullptr) {}
};

// --- Class to manage the BST ---
class BinarySearchTree {
public:
    TreeNode* root;

    BinarySearchTree() : root(nullptr) {}

    // Function to insert a new key in BST
    void insert(int key) {
        root = insertRec(root, key);
    }

private:
    // Helper function to insert a new key in BST recursively
    TreeNode* insertRec(TreeNode* node, int key) {
        if (node == nullptr) {
            return new TreeNode(key);
        }

        if (key < node->key) {
            node->left = insertRec(node->left, key);
        } else if (key > node->key) {
            node->right = insertRec(node->right, key);
        }

        return node;
    }
};

// --- Complexity Analysis ---
// Time: O(log n) for each operation (insert, search, delete)
// Space: O(n) for storing the tree

