// --- build prefix sum array ---

// Time: O(n^2) — Space: O(n^2)

#include <vector>
using namespace std;

vector<vector<long long>> buildPrefixSum(const vector<vector<int>>& grid) {
    int n = grid.size(), m = grid[0].size();
    vector<vector<long long>> prefix(n, vector<long long>(m, 0));

    // Compute prefix sums for each row
    for (int i = 0; i < n; ++i) {
        for (int j = 0; j < m; ++j) {
            prefix[i][j] = grid[i][j];
            if (j > 0) prefix[i][j] += prefix[i][j - 1]; // Add left prefix sum
        }
    }

    // Compute prefix sums for each column
    for (int j = 0; j < m; ++j) {
        for (int i = 0; i < n; ++i) {
            if (i > 0) prefix[i][j] += prefix[i - 1][j]; // Add top prefix sum
        }
    }

    return prefix;
}

// --- query range sum ---

// Time: O(1)
long long queryRangeSum(const vector<vector<long long>>& prefix, int r1, int c1, int r2, int c2) {
    long long result = prefix[r2][c2];
    if (r1 > 0) result -= prefix[r1 - 1][c2]; // Subtract top prefix sum
    if (c1 > 0) result -= prefix[r2][c1 - 1]; // Subtract left prefix sum
    if (r1 > 0 && c1 > 0) result += prefix[r1 - 1][c1 - 1]; // Add overlapping region back
    return result;
}

