// --- divide and conquer algorithm for finding the maximum subarray sum ---

#include <vector>
#include <algorithm>

// Function to find the maximum subarray sum using divide and conquer
long long maxSubArraySum(const std::vector<int>& nums, int left, int right) {
    // Base case: only one element
    if (left == right) return nums[left];

    // Find middle point
    int mid = left + (right - left) / 2;

    // Find maximum subarray sum in the left half
    long long maxLeftSum = maxSubArraySum(nums, left, mid);

    // Find maximum subarray sum in the right half
    long long maxRightSum = maxSubArraySum(nums, mid + 1, right);

    // Find maximum subarray sum such that it crosses the midpoint
    long long maxCrossingSum = INT_MIN;
    long long leftSum = 0;
    for (int i = mid; i >= left; --i) {
        leftSum += nums[i];
        if (leftSum > maxCrossingSum) {
            maxCrossingSum = leftSum;
        }
    }

    long long rightSum = 0;
    for (int i = mid + 1; i <= right; ++i) {
        rightSum += nums[i];
        if (rightSum > maxCrossingSum) {
            maxCrossingSum = rightSum;
        }
    }

    // Return the maximum of the three sums
    return std::max({maxLeftSum, maxRightSum, maxCrossingSum});
}

// Wrapper function to initialize the divide and conquer process
long long maxSubArray(const std::vector<int>& nums) {
    return maxSubArraySum(nums, 0, nums.size() - 1);
}

