template<typename T, typename Compare = std::less<T>>
class PriorityQueue {
public:
    // Constructor
    PriorityQueue() {}

    // Insert element
    void insert(const T& value) {
        pq.push(value);
    }

    // Extract maximum element
    T extractMax() {
        T max = pq.top();
        pq.pop();
        return max;
    }

    // Access maximum element
    T getMax() const {
        return pq.top();
    }

    // Check if priority queue is empty
    bool isEmpty() const {
        return pq.empty();
    }

private:
    std::priority_queue<T, std::vector<T>, Compare> pq;
};

