// --- Fibonacci Memoization ---

#include <vector>
#include <algorithm>

using namespace std;

// Function to compute nth Fibonacci number using memoization
long long fib(int n, vector<long long>& memo) {
    // Base cases
    if (n == 0) return 0;
    if (n == 1) return 1;

    // Check if the value is already computed
    if (memo[n] != -1) return memo[n];

    // Compute and store the value in memo table
    memo[n] = fib(n-1, memo) + fib(n-2, memo);
    return memo[n];
}

// Function to initialize memoization table and compute Fibonacci
long long fibonacci(int n) {
    vector<long long> memo(n+1, -1); // Initialize memo table with -1
    return fib(n, memo);
}

