// --- build dp table ---
std::vector<std::vector<int>> dp(A.size() + 1, std::vector<int>(B.size() + 1));

// --- fill dp table ---
for (int i = 1; i <= A.size(); ++i) {
    for (int j = 1; j <= B.size(); ++j) {
        if (A[i - 1] == B[j - 1]) {
            dp[i][j] = dp[i - 1][j - 1] + 1; // characters match, extend LCS
        } else {
            dp[i][j] = std::max(dp[i - 1][j], dp[i][j - 1]); // take max LCS from previous cells
        }
    }
}

// --- reconstruct lcs ---
std::string lcs;
int i = A.size(), j = B.size();
while (i > 0 && j > 0) {
    if (A[i - 1] == B[j - 1]) {
        lcs.push_back(A[i - 1]); // characters match, add to lcs
        --i;
        --j;
    } else if (dp[i - 1][j] > dp[i][j - 1]) {
        --i; // move up in dp table
    } else {
        --j; // move left in dp table
    }
}
std::reverse(lcs.begin(), lcs.end());

// return lcs length and sequence
return {dp[A.size()][B.size()], lcs};

walkthrough:
// --- build dp table ---
We initialize a 2D vector `dp` with dimensions (A.size() + 1) x (B.size() + 1) filled with zeros. This table will store the lengths of LCS for all subproblems.

// --- fill dp table ---
We iterate through each character of string A and B. If the characters match, we set `dp[i][j]` to `dp[i-1][j-1] + 1`, indicating that we extend the LCS by one character. If they don't match, we take the maximum value from either `dp[i-1][j]` or `dp[i][j-1]`, which represents the LCS length without including the current character from either string.

// --- reconstruct lcs ---
Starting from the bottom-right corner of the dp table, we backtrack to reconstruct one of the possible LCS sequences. If the characters match, we add the character to the LCS and move diagonally up-left. If they don't match, we move in the direction that gives the maximum LCS length (up or left). We reverse the constructed LCS at the end to get the correct order.

