// --- Kruskal's Algorithm for Minimum Spanning Tree ---

#include <vector>
#include <algorithm>
#include <iostream>

using namespace std;

struct Edge {
    int src, dest, weight;
};

// Comparator function used for sorting edges based on weight
bool compare(const Edge& a, const Edge& b) {
    return a.weight < b.weight;
}

// A structure to represent a subset for union-find
struct subset {
    int parent;
    int rank;
};

// Function to find set of an element i (uses path compression)
int find(subset subsets[], int i) {
    if (subsets[i].parent != i)
        subsets[i].parent = find(subsets, subsets[i].parent);
    return subsets[i].parent;
}

// Function to do union of two sets of x and y (uses union by rank)
void Union(subset subsets[], int x, int y) {
    int xroot = find(subsets, x);
    int yroot = find(subsets, y);

    // Attach smaller rank tree under root of high rank tree
    if (subsets[xroot].rank < subsets[yroot].rank)
        subsets[xroot].parent = yroot;
    else if (subsets[xroot].rank > subsets[yroot].rank)
        subsets[yroot].parent = xroot;

    // If ranks are same, then make one as root and increment its rank by one
    else {
        subsets[yroot].parent = xroot;
        subsets[xroot].rank++;
    }
}

// Function to construct MST using Kruskal's algorithm
void KruskalMST(vector<Edge>& edges, int V, int E) {
    // Sort all the edges in non-decreasing order of their weight
    sort(edges.begin(), edges.end(), compare);

    // Allocate memory for creating V subsets
    subset* subsets = new subset[V];
    for (int v = 0; v < V; ++v) {
        subsets[v].parent = v;
        subsets[v].rank = 0;
    }

    int e = 0; // An index variable, used for result[]
    int i = 0; // An index variable, used for sorted edges

    // Create V-1 edges for MST
    while (e < V - 1 && i < E) {
        // Pick the smallest edge and increment the index for next iteration
        Edge next_edge = edges[i++];

        int x = find(subsets, next_edge.src);
        int y = find(subsets, next_edge.dest);

        // If including this edge does't cause cycle, include it in result and increment the index of result for next edge
        if (x != y) {
            cout << next_edge.src << " -- " << next_edge.dest << " == " << next_edge.weight << endl;
            Union(subsets, x, y);
            e++;
        }
    }

    delete[] subsets;
}

// --- End of Kruskal's Algorithm ---

// --- Usage Example ---

int main() {
    int V = 4; // Number of vertices in graph
    int E = 5; // Number of edges in graph
    vector<Edge> edges(E);

    edges[0].src = 0;
    edges[0].dest = 1;
    edges[0].weight = 1;

    edges[1].src = 0;
    edges[1].dest = 2;
    edges[1].weight = 2;

    edges[2].src = 0;
    edges[2].dest = 3;
    edges[2].weight = 3;

    edges[3].src = 1;
    edges[3].dest = 2;
    edges[3].weight = 4;

    edges[4].src = 1;
    edges[4].dest = 3;
    edges[4].weight = 5;

    KruskalMST(edges, V, E);

    return 0;
}

