    std::vector<std::vector<int>> adj(n);
    for (const auto& [u, v] : edges) {
        adj[u].push_back(v);
        adj[v].push_back(u);
    }
    return adj;
}

// --- bipartite check & 2-coloring ---
bool is_bipartite(const std::vector<std::vector<int>>& adj, int start) {
    std::vector<int> color(adj.size(), -1); // -1 means uncolored
    std::queue<int> q;
    q.push(start);
    color[start] = 0; // Start with color 0 (red)

    while (!q.empty()) {
        int u = q.front();
        q.pop();

        for (int v : adj[u]) {
            if (color[v] == -1) { // If uncolored, color it and enqueue
                color[v] = 1 - color[u]; // Alternate color
                q.push(v);
            } else if (color[v] == color[u]) { // If already colored and same as u, not bipartite
                return false;
            }
        }
    }
    return true;
}

// --- check all connected components ---
bool is_bipartite(const std::vector<std::vector<int>>& adj) {
    int n = adj.size();
    std::vector<bool> visited(n, false);

    for (int i = 0; i < n; ++i) {
        if (!visited[i] && !is_bipartite(adj, i)) {
            return false;
        }
    }
    return true;
}

