std::vector<std::vector<int>> build_adjacency_list(const std::vector<int>& edges) {
    int n = edges.size() / 2;
    std::vector<std::vector<int>> adj(n);
    for (int i = 0; i < n; ++i) {
        adj[edges[2 * i]].push_back(edges[2 * i + 1]);
        adj[edges[2 * i + 1]].push_back(edges[2 * i]);
    }
    return adj;
}

// --- bfs function ---
std::vector<int> bfs(const std::vector<std::vector<int>>& adj, int start) {
    int n = adj.size();
    std::vector<bool> visited(n, false);
    std::vector<int> result;
    std::queue<int> q;

    q.push(start);
    visited[start] = true;

    while (!q.empty()) {
        int u = q.front();
        q.pop();
        result.push_back(u);

        for (int v : adj[u]) {
            if (!visited[v]) {
                q.push(v);
                visited[v] = true;
            }
        }
    }

    return result;
}

