// --- Multi-Source BFS Implementation ---

// Time: O(n + m) — Space: O(n)

#include <vector>
#include <queue>
#include <unordered_set>

using namespace std;

// Function to perform Multi-Source BFS on a graph
vector<int> multiSourceBFS(const vector<vector<int>>& graph, const vector<int>& sources) {
    int n = graph.size();
    vector<int> distances(n, -1); // Initialize distances with -1 (unreachable)
    queue<int> q;
    unordered_set<int> visited;

    // Initialize the queue with all source nodes
    for (int src : sources) {
        q.push(src);
        distances[src] = 0;
        visited.insert(src);
    }

    // Process the queue until it's empty
    while (!q.empty()) {
        int u = q.front();
        q.pop();

        // Explore all adjacent nodes
        for (int v : graph[u]) {
            if (!visited.count(v)) {
                visited.insert(v);
                distances[v] = distances[u] + 1;
                q.push(v);
            }
        }
    }

    return distances;
}

