// --- Binary Exponentiation ---

// Function to compute (base^exponent) % mod using binary exponentiation
long long binaryExponentiation(long long base, long long exponent, long long mod) {
    long long result = 1; // Initialize result
    base = base % mod; // Update base if it is more than or equal to mod

    // Loop until all bits of exponent are processed
    while (exponent > 0) {
        // If the least significant bit is set, multiply result with base
        if (exponent & 1)
            result = (result * base) % mod;

        // Square the base and reduce it modulo mod
        base = (base * base) % mod;

        // Right shift exponent by 1
        exponent >>= 1;
    }

    return result;
}

