// --- Prime Factorization using Pollard's Rho algorithm ---

#include <vector>
#include <algorithm>
#include <numeric>
#include <cmath>

// Function to perform prime factorization using Pollard's Rho algorithm
std::vector<long long> pollardsRho(long long n) {
    if (n % 2 == 0) return {2}; // Handle even numbers separately
    long long x = 2, y = 2, d = 1;
    while (d == 1) {
        x = (x * x + 1) % n; // f(x) = x^2 + 1
        y = (y * y + 1) % n;
        y = (y * y + 1) % n;
        d = std::gcd(std::abs(x - y), n);
    }
    if (d == n) return pollardsRho(n); // If no factor found, recurse
    std::vector<long long> factors = pollardsRho(d);
    factors.insert(factors.end(), pollardsRho(n / d).begin(), pollardsRho(n / d).end());
    return factors;
}

// --- Helper function to print the factors ---
void printFactors(const std::vector<long long>& factors) {
    for (long long factor : factors) {
        std::cout << factor << " ";
    }
    std::cout << std::endl;
}

