// --- build adjacency list ---
// Function to calculate combinations using Pascal's triangle
vector<vector<long long>> build_combinations(int n) {
    vector<vector<long long>> comb(n + 1, vector<long long>(n + 1, 0));
    for (int i = 0; i <= n; ++i) {
        comb[i][0] = 1; // Base case: choose 0 from any number is 1
        for (int j = 1; j <= i; ++j) {
            comb[i][j] = comb[i - 1][j - 1] + comb[i - 1][j]; // Recursive relation
        }
    }
    return comb;
}

// --- calculate distributions ---
// Function to distribute n indistinguishable items into k distinguishable bins
long long distribute_stars_and_bars(int n, int k) {
    vector<vector<long long>> comb = build_combinations(n + k - 1);
    return comb[n + k - 1][k - 1]; // Number of non-negative integer solutions
}

// --- calculate positive distributions ---
// Function to distribute n indistinguishable items into k distinguishable bins with each bin having at least one item
long long distribute_stars_and_bars_positive(int n, int k) {
    vector<vector<long long>> comb = build_combinations(n - 1);
    return comb[n - 1][k - 1]; // Number of positive integer solutions
}

