// --- coordinate compression ---

#include <vector>
#include <map>
#include <algorithm>

// Time: O(n log n) — Space: O(n)
std::vector<int> compress_coordinates(const std::vector<int>& coords) {
    // --- collect unique elements ---
    std::set<int> unique_coords(coords.begin(), coords.end());

    // --- assign ranks based on sorted positions ---
    std::map<int, int> rank_map;
    int rank = 0;
    for (const auto& coord : unique_coords) {
        rank_map[coord] = rank++;
    }

    // --- replace each element with its rank ---
    std::vector<int> compressed_coords;
    for (const auto& coord : coords) {
        compressed_coords.push_back(rank_map[coord]);
    }

    return compressed_coords;
}

