// --- Sliding Window Implementation ---

// Time: O(n) — Space: O(k)

#include <vector>
#include <unordered_set>

using namespace std;

int longestUniqueSubarray(const vector<int>& nums) {
    unordered_set<int> window; // Stores unique elements in the current window
    int left = 0, right = 0, maxLength = 0;

    while (right < nums.size()) {
        // Expand the window by moving the right pointer
        while (right < nums.size() && window.find(nums[right]) == window.end()) {
            window.insert(nums[right]);
            right++;
        }

        // Update the maximum length found so far
        maxLength = max(maxLength, right - left);

        // Contract the window by moving the left pointer
        while (left < right && window.find(nums[right]) != window.end()) {
            window.erase(nums[left]);
            left++;
        }
    }

    return maxLength;
}

