// --- AVL Tree Implementation ---

// Time: O(log n) for insert, delete, search
// Space: O(n) for storing the tree nodes

#include <iostream>
#include <memory>

struct Node {
    int key;
    std::shared_ptr<Node> left, right;
    int height;

    Node(int k) : key(k), left(nullptr), right(nullptr), height(1) {}
};

// --- Helper Functions ---

int height(std::shared_ptr<Node> node) {
    return (node == nullptr) ? 0 : node->height;
}

int balanceFactor(std::shared_ptr<Node> node) {
    return height(node->left) - height(node->right);
}

std::shared_ptr<Node> rightRotate(std::shared_ptr<Node> y) {
    std::shared_ptr<Node> x = y->left;
    std::shared_ptr<Node> T2 = x->right;

    x->right = y;
    y->left = T2;

    y->height = std::max(height(y->left), height(y->right)) + 1;
    x->height = std::max(height(x->left), height(x->right)) + 1;

    return x;
}

std::shared_ptr<Node> leftRotate(std::shared_ptr<Node> x) {
    std::shared_ptr<Node> y = x->right;
    std::shared_ptr<Node> T2 = y->left;

    y->left = x;
    x->right = T2;

    x->height = std::max(height(x->left), height(x->right)) + 1;
    y->height = std::max(height(y->left), height(y->right)) + 1;

    return y;
}

std::shared_ptr<Node> insert(std::shared_ptr<Node> node, int key) {
    if (node == nullptr)
        return std::make_shared<Node>(key);

    if (key < node->key)
        node->left = insert(node->left, key);
    else if (key > node->key)
        node->right = insert(node->right, key);
    else
        return node; // Duplicate keys are not allowed

    node->height = 1 + std::max(height(node->left), height(node->right));

    int balance = balanceFactor(node);

    if (balance > 1 && key < node->left->key)
        return rightRotate(node);

    if (balance < -1 && key > node->right->key)
        return leftRotate(node);

    if (balance > 1 && key > node->left->key) {
        node->left = leftRotate(node->left);
        return rightRotate(node);
    }

    if (balance < -1 && key < node->right->key) {
        node->right = rightRotate(node->right);
        return leftRotate(node);
    }

    return node;
}

