// --- DSU (Disjoint Set Union) Implementation ---

// Time: O(alpha(n)) per operation — Space: O(n)

#include <vector>
#include <algorithm>

struct DSU {
    std::vector<int> parent, rank;

    // Initialize the DSU with n elements
    DSU(int n) : parent(n), rank(n, 1) {
        for (int i = 0; i < n; ++i) {
            parent[i] = i; // Each element is its own parent initially
        }
    }

    // Find the root of the set containing x with path compression
    int find(int x) {
        if (parent[x] != x) {
            parent[x] = find(parent[x]); // Path compression
        }
        return parent[x];
    }

    // Union the sets containing x and y by rank
    void unite(int x, int y) {
        int rootX = find(x);
        int rootY = find(y);

        if (rootX != rootY) {
            if (rank[rootX] > rank[rootY]) {
                parent[rootY] = rootX; // Attach smaller tree to larger one
            } else if (rank[rootX] < rank[rootY]) {
                parent[rootX] = rootY;
            } else {
                parent[rootY] = rootX;
                rank[rootX] += 1; // Increment rank if trees are of equal size
            }
        }
    }
};

