// --- Fenwick Tree (BIT) Implementation ---

// Time: O(log n) for update and query operations
// Space: O(n)

#include <vector>

using namespace std;

class FenwickTree {
public:
    FenwickTree(int n) : tree(n + 1, 0) {}

    // Update the value at index i by adding delta
    void update(int i, int delta) {
        while (i < tree.size()) {
            tree[i] += delta;
            i += i & -i;
        }
    }

    // Get the prefix sum up to index i
    int query(int i) {
        int sum = 0;
        while (i > 0) {
            sum += tree[i];
            i -= i & -i;
        }
        return sum;
    }

private:
    vector<int> tree;
};

