// --- Shunting Yard Algorithm ---

#include <vector>
#include <stack>
#include <string>
#include <cctype>

// Function to determine the precedence of operators
int precedence(char op) {
    if (op == '+' || op == '-') return 1;
    if (op == '*' || op == '/') return 2;
    return 0;
}

// Function to check if a character is an operator
bool isOperator(char c) {
    return c == '+' || c == '-' || c == '*' || c == '/';
}

// Function to perform the operation based on the operator and operands
int applyOp(int a, int b, char op) {
    switch (op) {
        case '+': return a + b;
        case '-': return a - b;
        case '*': return a * b;
        case '/': return a / b;
    }
    return 0;
}

// Function to evaluate the expression using Shunting Yard Algorithm
int evaluate(const std::string& tokens) {
    std::stack<int> values;
    std::stack<char> ops;

    for (size_t i = 0; i < tokens.length(); ++i) {
        // If the current token is a whitespace, skip it
        if (tokens[i] == ' ') continue;

        // If the current token is an operand, push it to the values stack
        if (isdigit(tokens[i])) {
            int val = 0;
            while (i < tokens.length() && isdigit(tokens[i])) {
                val = (val * 10) + (tokens[i] - '0');
                ++i;
            }
            values.push(val);
            --i; // Adjust index since the loop increments it
        }

        // If the current token is an operator
        else if (isOperator(tokens[i])) {
            // While the top of 'ops' has same or greater precedence to current
token, which is an operator. Apply operator on top of 'ops' to top two elements in values stack.
            while (!ops.empty() && precedence(ops.top()) >= precedence(tokens[i])) {
                int val2 = values.top(); values.pop();
                int val1 = values.top(); values.pop();
                char op = ops.top(); ops.pop();
                values.push(applyOp(val1, val2, op));
            }
            ops.push(tokens[i]);
        }
    }

    // Entire expression has been parsed at this point, apply remaining ops to remaining values
    while (!ops.empty()) {
        int val2 = values.top(); values.pop();
        int val1 = values.top(); values.pop();
        char op = ops.top(); ops.pop();
        values.push(applyOp(val1, val2, op));
    }

    // Top of 'values' contains the result, return it
    return values.top();
}

