// --- Time Complexity: O(n) ---
// --- Space Complexity: O(n) ---

#include <vector>
#include <stack>

long long largestRectangleArea(const std::vector<int>& heights) {
    int n = heights.size();
    std::stack<int> s;
    std::vector<int> left(n), right(n);

    // Fill left array with previous smaller element indices
    for (int i = 0; i < n; ++i) {
        while (!s.empty() && heights[s.top()] >= heights[i]) {
            s.pop();
        }
        left[i] = s.empty() ? -1 : s.top();
        s.push(i);
    }

    // Clear stack for reuse
    while (!s.empty()) {
        s.pop();
    }

    // Fill right array with next smaller element indices
    for (int i = n - 1; i >= 0; --i) {
        while (!s.empty() && heights[s.top()] >= heights[i]) {
            s.pop();
        }
        right[i] = s.empty() ? n : s.top();
        s.push(i);
    }

    // Calculate the maximum area
    long long maxArea = 0;
    for (int i = 0; i < n; ++i) {
        maxArea = std::max(maxArea, static_cast<long long>(heights[i]) * (right[i] - left[i] - 1));
    }

    return maxArea;
}

