// --- Interval DP Implementation ---

// Time: O(n^2) — Space: O(n^2)

#include <vector>
#include <algorithm>

using namespace std;

// Function to compute the minimum number of operations to make all elements in an array equal
int minOperations(vector<int>& arr) {
    int n = arr.size();
    vector<vector<int>> dp(n, vector<int>(n, 0));

    // --- Build DP Table ---
    for (int length = 2; length <= n; ++length) {
        for (int i = 0; i <= n - length; ++i) {
            int j = i + length - 1;
            dp[i][j] = INT_MAX;

            // --- Consider all possible split points ---
            for (int k = i; k < j; ++k) {
                dp[i][j] = min(dp[i][j], dp[i][k] + dp[k+1][j] + abs(arr[i] - arr[j]));
            }
        }
    }

    return dp[0][n-1];
}

