// --- LCIS function ---

// Function to find the length of the Longest Common Increasing Subsequence (LCIS)
int lcis(const vector<int>& A, const vector<int>& B) {
    int n = A.size(), m = B.size();
    vector<int> tails;

    // --- iterate through elements of both sequences ---
    for (int i = 0; i < n; ++i) {
        for (int j = 0; j < m; ++j) {
            if (A[i] == B[j]) {
                // --- binary search to find the position to update tails ---
                auto it = lower_bound(tails.begin(), tails.end(), A[i]);
                if (it == tails.end()) {
                    tails.push_back(A[i]);
                } else {
                    *it = A[i];
                }
            }
        }
    }

    // --- the length of LCIS is the size of tails array ---
    return tails.size();
}

