// --- Matrix Chain Multiplication ---

#include <vector>
#include <algorithm>

// Function to perform matrix chain multiplication
std::vector<std::vector<int>> matrixChainMultiplication(const std::vector<int>& dimensions) {
    int n = dimensions.size() - 1;
    std::vector<std::vector<int>> m(n, std::vector<int>(n, 0));
    std::vector<std::vector<int>> s(n, std::vector<int>(n, 0));

    // --- build adjacency list ---
    for (int l = 2; l <= n; ++l) { // l is the chain length
        for (int i = 0; i <= n - l; ++i) {
            int j = i + l;
            m[i][j] = INT_MAX;
            for (int k = i; k < j; ++k) {
                int q = m[i][k] + m[k+1][j] + dimensions[i] * dimensions[k+1] * dimensions[j];
                if (q < m[i][j]) {
                    m[i][j] = q;
                    s[i][j] = k;
                }
            }
        }
    }

    return m;
}

