// --- build adjacency list ---
std::vector<std::vector<int>> build_adjacency_list(const std::vector<std::pair<int, int>>& edges, int n) {
    std::vector<std::vector<int>> adj(n);
    for (const auto& [u, v] : edges) {
        adj[u].push_back(v);
        adj[v].push_back(u);
    }
    return adj;
}

// --- dfs to find basis ---
void dfs(int node, int parent, std::vector<int>& basis, const std::vector<std::vector<int>>& adj) {
    for (int neighbor : adj[node]) {
        if (neighbor != parent) {
            dfs(neighbor, node, basis, adj);
            // --- update basis ---
            for (int i = 0; i < basis.size(); ++i) {
                if ((basis[i] ^ neighbor) == 0) {
                    basis[i] = neighbor;
                    break;
                }
            }
        }
    }
}

// --- xor dp function ---
long long xor_dp(int node, int parent, const std::vector<std::vector<int>>& adj, const std::vector<int>& basis) {
    long long result = 0;
    for (int neighbor : adj[node]) {
        if (neighbor != parent) {
            result ^= xor_dp(neighbor, node, adj, basis);
        }
    }
    // --- update result with basis ---
    for (int i = 0; i < basis.size(); ++i) {
        if ((node ^ basis[i]) == 0) {
            result ^= basis[i];
            break;
        }
    }
    return result;
}

// --- main function ---
long long solve(const std::vector<std::pair<int, int>>& edges, int n) {
    auto adj = build_adjacency_list(edges, n);
    std::vector<int> basis;
    dfs(0, -1, basis, adj);
    return xor_dp(0, -1, adj, basis);
}

