// --- Amortized Analysis Example ---

// Define a class for a dynamic array with amortized O(1) insertions
struct DynamicArray {
    vector<int> data;
    int capacity;

    // Constructor
    DynamicArray() : capacity(1), data(capacity) {}

    // Amortized O(1) insertion
    void insert(int value) {
        if (data.size() == capacity) {
            // Double the capacity and copy elements to new array
            capacity *= 2;
            vector<int> newData(capacity);
            copy(data.begin(), data.end(), newData.begin());
            data = move(newData);
        }
        data.push_back(value);
    }
};

// --- Complexity Analysis ---
// Time: O(n) for n insertions (amortized O(1) per insertion)
// Space: O(n)

// --- Usage Example ---
// DynamicArray arr;
// arr.insert(10);
// arr.insert(20);
// arr.insert(30);
// // arr now contains [10, 20, 30]

// --- Notes ---
// - Amortized analysis spreads the cost of resizing across multiple insertions
// - Use vector for dynamic array implementation
// - Avoid unnecessary copies by using move semantics
// - Be mindful of iterator invalidation during resize

