// --- Time Complexity: O(n log n) due to sorting
// --- Space Complexity: O(n) for storing the hull points

#include <vector>
#include <algorithm>
#include <cmath>

struct Point {
    long long x, y;
};

// Function to calculate the orientation of ordered triplet (p, q, r)
// 0 -> p, q and r are collinear
// 1 -> Clockwise
// 2 -> Counterclockwise
int orientation(Point p, Point q, Point r) {
    long long val = (q.y - p.y) * (r.x - q.x) - (q.x - p.x) * (r.y - q.y);
    if (val == 0) return 0;  // collinear
    return (val > 0) ? 1 : 2; // clock or counterclock wise
}

// Function to compare two points based on polar angle with respect to p
bool compare(const Point &p1, const Point &p2) {
    int o = orientation(p1, p2, hull[0]);
    if (o == 0)
        return (dist(p1, hull[0]) >= dist(p2, hull[0]));
    return (o == 2);
}

// Function to calculate the distance between two points
long long dist(Point p1, Point p2) {
    return (p1.x - p2.x) * (p1.x - p2.x) + (p1.y - p2.y) * (p1.y - p2.y);
}

// Function to find the convex hull using Graham Scan algorithm
std::vector<Point> convexHull(std::vector<Point> points) {
    if (points.size() <= 3) return points;

    // Find the leftmost point
    int l = 0;
    for (int i = 1; i < points.size(); i++)
        if (points[i].x < points[l].x)
            l = i;

    // Place the leftmost point at the beginning of the array
    std::swap(points[0], points[l]);

    // Sort the remaining points by polar angle with respect to the first point
    std::sort(points.begin() + 1, points.end(), compare);

    // Create an empty stack and push the first three points to it
    hull.clear();
    hull.push_back(points[0]);
    hull.push_back(points[1]);
    hull.push_back(points[2]);

    // Process remaining points
    for (int i = 3; i < points.size(); i++) {
        while (hull.size() >= 2 && orientation(hull[hull.size() - 2], hull.back(), points[i]) != 2)
            hull.pop_back();
        hull.push_back(points[i]);
    }

    return hull;
}

