// --- Point structure ---
struct Point {
    long long x, y;
    Point(long long x = 0, long long y = 0) : x(x), y(y) {}
};

// --- Cross product of two vectors ---
long long crossProduct(const Point& a, const Point& b) {
    return a.x * b.y - a.y * b.x;
}

// --- Distance between two points ---
long long distance(const Point& a, const Point& b) {
    return abs(a.x - b.x) + abs(a.y - b.y);
}

// --- Check if point is on the left of the line defined by two points ---
bool isLeft(const Point& p, const Point& q, const Point& r) {
    return crossProduct(q - p, r - p) > 0;
}

// --- Check if point is on the right of the line defined by two points ---
bool isRight(const Point& p, const Point& q, const Point& r) {
    return crossProduct(q - p, r - p) < 0;
}

// --- Check if point is collinear with the line defined by two points ---
bool isCollinear(const Point& p, const Point& q, const Point& r) {
    return crossProduct(q - p, r - p) == 0;
}

