for (const auto& line : lines) {
    // Remove lines that are no longer in the sweep line's range
    while (!active_lines.empty() && active_lines.begin()->second < line.first) {
        active_lines.erase(active_lines.begin());
    }
    // Check for intersections with active lines
    for (auto it = active_lines.lower_bound(line.first); it != active_lines.end(); ++it) {
        long long x = line.first;
        long long y1 = (*it).first;
        long long y2 = (*std::next(it, -1)).first;
        if (y1 != y2) {
            intersections.emplace_back(x, (y1 * x - y2 * x) / (y1 - y2));
        }
    }
    // Add the current line to the active set
    active_lines.insert({line.second, line.first});
}

