// --- build adjacency list ---
std::vector<std::vector<int>> build_adjacency_list(int n, const std::vector<std::pair<int, int>>& edges) {
    std::vector<std::vector<int>> adj(n + 1);
    for (const auto& [u, v] : edges) {
        adj[u].push_back(v);
        adj[v].push_back(u);
    }
    return adj;
}

// --- Tarjan's algorithm to find bridges ---
void tarjan(int u, int p, std::vector<int>& disc, std::vector<int>& low, std::vector<bool>& in_stack, std::stack<int>& st, std::vector<std::pair<int, int>>& bridges) {
    static int time = 0;
    disc[u] = low[u] = ++time;
    in_stack[u] = true;
    st.push(u);

    for (int v : adj[u]) {
        if (v == p) continue; // Skip parent edge
        if (!disc[v]) {
            tarjan(v, u, disc, low, in_stack, st, bridges);
            low[u] = std::min(low[u], low[v]);
            if (low[v] > disc[u]) {
                bridges.push_back({u, v}); // (u, v) is a bridge
            }
        } else if (in_stack[v]) {
            low[u] = std::min(low[u], disc[v]);
        }
    }

    if (disc[u] == low[u]) {
        while (st.top() != u) {
            int v = st.top(); st.pop();
            in_stack[v] = false;
        }
        st.pop();
        in_stack[u] = false;
    }
}

// --- 2-Edge-Connected Components ---
std::vector<std::vector<int>> two_edge_connected_components(int n, const std::vector<std::pair<int, int>>& edges) {
    std::vector<std::vector<int>> adj = build_adjacency_list(n, edges);
    std::vector<int> disc(n + 1, 0), low(n + 1, 0);
    std::vector<bool> in_stack(n + 1, false);
    std::stack<int> st;
    std::vector<std::pair<int, int>> bridges;

    for (int i = 1; i <= n; ++i) {
        if (!disc[i]) {
            tarjan(i, -1, disc, low, in_stack, st, bridges);
        }
    }

    // Remove bridges from the graph
    std::vector<std::vector<int>> new_adj(n + 1);
    for (int i = 1; i <= n; ++i) {
        for (int v : adj[i]) {
            if (std::find(bridges.begin(), bridges.end(), std::make_pair(i, v)) == bridges.end()) {
                new_adj[i].push_back(v);
                new_adj[v].push_back(i);
            }
        }
    }

    // Find biconnected components
    std::vector<std::vector<int>> bcc;
    std::vector<bool> visited(n + 1, false);

    for (int i = 1; i <= n; ++i) {
        if (!visited[i]) {
            std::vector<int> component;
            dfs(i, -1, new_adj, visited, component);
            bcc.push_back(component);
        }
    }

    return bcc;
}

// --- DFS for finding biconnected components ---
void dfs(int u, int p, const std::vector<std::vector<int>>& adj, std::vector<bool>& visited, std::vector<int>& component) {
    visited[u] = true;
    component.push_back(u);

    for (int v : adj[u]) {
        if (v == p) continue; // Skip parent edge
        if (!visited[v]) {
            dfs(v, u, adj, visited, component);
        }
    }
}

