// --- Tarjan's algorithm for BCCs ---
std::vector<std::vector<int>> bccs(const std::vector<std::vector<int>>& adj) {
    int time = 0;
    std::vector<int> disc(adj.size(), -1);
    std::vector<int> low(adj.size(), -1);
    std::vector<bool> in_stack(adj.size(), false);
    std::stack<int> stack;
    std::vector<std::vector<int>> bccs;

    auto dfs = [&](auto&& dfs, int u, int parent) -> void {
        disc[u] = low[u] = time++;
        stack.push(u);
        in_stack[u] = true;

        for (int v : adj[u]) {
            if (v == parent) continue;
            if (disc[v] == -1) {
                dfs(dfs, v, u);
                low[u] = std::min(low[u], low[v]);
                if (low[v] >= disc[u]) {
                    bccs.push_back({u, v});
                    while (true) {
                        int w = stack.top();
                        stack.pop();
                        in_stack[w] = false;
                        if (w == v) break;
                    }
                }
            } else if (in_stack[v]) {
                low[u] = std::min(low[u], disc[v]);
            }
        }
    };

    for (int i = 0; i < adj.size(); ++i) {
        if (disc[i] == -1) {
            dfs(dfs, i, -1);
        }
    }

    return bccs;
}

