// --- build adjacency list ---
std::unordered_map<int, std::vector<int>> build_adjacency_list(const std::vector<std::pair<int, int>>& edges) {
    std::unordered_map<int, std::vector<int>> adj_list;
    for (const auto& [u, v] : edges) {
        adj_list[u].push_back(v);
        adj_list[v].push_back(u);
    }
    return adj_list;
}

// --- bidirectional BFS ---
long long bidirectional_bfs(int source, int target, const std::unordered_map<int, std::vector<int>>& adj_list) {
    if (source == target) return 0;

    std::queue<int> forward_queue, backward_queue;
    std::unordered_set<int> forward_visited, backward_visited;

    forward_queue.push(source);
    backward_queue.push(target);
    forward_visited.insert(source);
    backward_visited.insert(target);

    int level = 0;

    while (!forward_queue.empty() && !backward_queue.empty()) {
        ++level;

        // Expand forward queue
        for (size_t size = forward_queue.size(); size > 0; --size) {
            int u = forward_queue.front();
            forward_queue.pop();

            for (int v : adj_list[u]) {
                if (backward_visited.count(v)) return level + backward_visited[v];
                if (!forward_visited.count(v)) {
                    forward_visited.insert(v);
                    forward_queue.push(v);
                }
            }
        }

        // Expand backward queue
        for (size_t size = backward_queue.size(); size > 0; --size) {
            int u = backward_queue.front();
            backward_queue.pop();

            for (int v : adj_list[u]) {
                if (forward_visited.count(v)) return level + forward_visited[v];
                if (!backward_visited.count(v)) {
                    backward_visited.insert(v);
                    backward_queue.push(v);
                }
            }
        }
    }

    return -1; // No path found
}

