            low[u] = min(low[u], low[v]);

            if (low[v] > disc[u]) {
                bridges.push_back(e.id); // (u, v) is a bridge
            }
        } else if (in_stack[v]) { // back edge
            low[u] = min(low[u], disc[v]);
        }
    }

    if (p == -1 && children[u] > 1) {
        articulation_points.push_back(u); // root is an articulation point if it has more than one child
    } else if (p != -1 && low[u] >= disc[p]) {
        articulation_points.push_back(p); // non-root is an articulation point if it doesn't have a back edge to an ancestor
    }

    in_stack[u] = false;
}

// --- main function ---
vector<pair<int, int>> findBridgesAndArticulationPoints(const Graph& graph) {
    int V = graph.size();
    vector<int> disc(V, 0), low(V, 0);
    vector<bool> in_stack(V, false);
    vector<vector<int>> bridges;
    vector<int> articulation_points;

    int time = 0;
    for (int i = 0; i < V; ++i) {
        if (!disc[i]) {
            tarjan(i, -1, time, disc, low, in_stack, bridges, articulation_points);
        }
    }

    return {bridges.begin(), bridges.end()}, articulation_points;
}

