// --- Condensation DAG Construction ---
std::vector<int> condensation_dag;
std::vector<std::vector<int>> dag_adj;

void build_condensation_dag(int n, const std::vector<std::vector<int>>& adj) {
    dag_adj.resize(n);
    for (int u = 0; u < n; ++u) {
        for (int v : adj[u]) {
            if (scc_ids[u] != scc_ids[v]) {
                dag_adj[scc_ids[u]].push_back(scc_ids[v]);
            }
        }
    }
}

// --- Topological Sort ---
std::vector<int> topological_sort(int n, const std::vector<std::vector<int>>& adj) {
    std::vector<int> in_degree(n, 0);
    for (int u = 0; u < n; ++u) {
        for (int v : adj[u]) {
            ++in_degree[v];
        }
    }

    std::queue<int> q;
    for (int u = 0; u < n; ++u) {
        if (in_degree[u] == 0) {
            q.push(u);
        }
    }

    std::vector<int> result;
    while (!q.empty()) {
        int u = q.front();
        q.pop();
        result.push_back(u);
        for (int v : adj[u]) {
            --in_degree[v];
            if (in_degree[v] == 0) {
                q.push(v);
            }
        }
    }

    return result;
}

// --- Main Function ---
std::vector<int> condensation_dag(int n, const std::vector<std::pair<int, int>>& edges) {
    auto adj = build_adjacency_list(n, edges);
    tarjan_scc(n, adj);
    build_condensation_dag(n, adj);

    return topological_sort(n, dag_adj);
}

