// --- build adjacency list ---
std::vector<std::vector<int>> build_adjacency_list(const std::vector<std::pair<int, int>>& edges, int n) {
    std::vector<std::vector<int>> adj(n);
    for (const auto& [u, v] : edges) {
        adj[u].push_back(v);
        adj[v].push_back(u);
    }
    return adj;
}

// --- DFS to find back edges ---
void dfs(int node, int parent, const std::vector<std::vector<int>>& adj, std::vector<bool>& visited, std::vector<int>& discovery_time, std::vector<int>& low_link, std::vector<bool>& on_stack, std::vector<std::pair<int, int>>& back_edges) {
    static int time = 0;
    visited[node] = true;
    discovery_time[node] = low_link[node] = ++time;
    on_stack[node] = true;

    for (int neighbor : adj[node]) {
        if (!visited[neighbor]) {
            dfs(neighbor, node, adj, visited, discovery_time, low_link, on_stack, back_edges);
            low_link[node] = std::min(low_link[node], low_link[neighbor]);
            if (low_link[neighbor] > discovery_time[node]) {
                back_edges.push_back({node, neighbor});
            }
        } else if (neighbor != parent && on_stack[neighbor]) {
            low_link[node] = std::min(low_link[node], discovery_time[neighbor]);
            back_edges.push_back({node, neighbor});
        }
    }

    on_stack[node] = false;
}

// --- DFS Tree & Back Edges ---
std::pair<std::vector<int>, std::vector<std::pair<int, int>>> dfs_tree_and_back_edges(const std::vector<std::pair<int, int>>& edges, int n) {
    std::vector<std::vector<int>> adj = build_adjacency_list(edges, n);
    std::vector<bool> visited(n, false);
    std::vector<int> discovery_time(n, -1);
    std::vector<int> low_link(n, -1);
    std::vector<bool> on_stack(n, false);
    std::vector<std::pair<int, int>> back_edges;

    for (int i = 0; i < n; ++i) {
        if (!visited[i]) {
            dfs(i, -1, adj, visited, discovery_time, low_link, on_stack, back_edges);
        }
    }

    return {discovery_time, back_edges};
}

