// --- Kosaraju's Algorithm for SCCs ---

#include <vector>
#include <stack>
#include <algorithm>

using namespace std;
typedef vector<vector<int>> Graph;
typedef vector<int> vi;

// --- build adjacency list ---
Graph build_adjacency_list(int n, const vector<pair<int, int>>& edges) {
    Graph adj(n);
    for (auto& [u, v] : edges) {
        adj[u].push_back(v);
    }
    return adj;
}

// --- Kosaraju's Algorithm ---
void kosaraju(int u, const Graph& adj, vi& visited, stack<int>& st) {
    visited[u] = 1;
    for (int v : adj[u]) {
        if (!visited[v]) {
            kosaraju(v, adj, visited, st);
        }
    }
    st.push(u);
}

void kosaraju_scc(const Graph& adj, int n, vector<vi>& sccs) {
    vi visited(n, 0);
    stack<int> st;

    // First DFS to fill stack with nodes in finishing order
    for (int i = 0; i < n; ++i) {
        if (!visited[i]) {
            kosaraju(i, adj, visited, st);
        }
    }

    // Transpose the graph
    Graph adjT(n);
    for (int u = 0; u < n; ++u) {
        for (int v : adj[u]) {
            adjT[v].push_back(u);
        }
    }

    visited.assign(n, 0);

    // Second DFS to find SCCs
    while (!st.empty()) {
        int u = st.top();
        st.pop();
        if (!visited[u]) {
            vi scc;
            kosaraju(u, adjT, visited, scc);
            sccs.push_back(scc);
        }
    }
}

// --- Tarjan's Algorithm for SCCs ---
void tarjan(int u, int& time, const Graph& adj, vi& disc, vi& low, stack<int>& st, vi& in_stack, vector<vi>& sccs) {
    disc[u] = low[u] = ++time;
    st.push(u);
    in_stack[u] = 1;

    for (int v : adj[u]) {
        if (disc[v] == -1) { // unvisited
            tarjan(v, time, adj, disc, low, st, in_stack, sccs);
            low[u] = min(low[u], low[v]);
        } else if (in_stack[v]) { // in stack
            low[u] = min(low[u], disc[v]);
        }
    }

    if (disc[u] == low[u]) { // a new SCC is found
        vi scc;
        while (true) {
            int v = st.top();
            st.pop();
            in_stack[v] = 0;
            scc.push_back(v);
            if (v == u) break;
        }
        sccs.push_back(scc);
    }
}

void tarjan_scc(const Graph& adj, int n, vector<vi>& sccs) {
    vi disc(n, -1), low(n, -1);
    stack<int> st;
    vi in_stack(n, 0);
    int time = 0;

    for (int i = 0; i < n; ++i) {
        if (disc[i] == -1) {
            tarjan(i, time, adj, disc, low, st, in_stack, sccs);
        }
    }
}

