// --- Exchange Argument Implementation ---

// Function to perform the exchange argument on an array
std::vector<int> exchangeArgument(std::vector<int>& arr) {
    int n = arr.size();
    bool swapped;

    // --- Perform swaps until no more improvements can be made ---
    do {
        swapped = false;
        for (int i = n - 2; i >= 0; --i) {
            if (arr[i] > arr[i + 1]) {
                std::swap(arr[i], arr[i + 1]); // Swap elements to improve the solution
                swapped = true;
            }
        }
    } while (swapped);

    return arr;
}

