// --- Greedy Scheduling Problem ---

// Time Complexity: O(n log n) due to sorting
// Space Complexity: O(1) extra space

#include <vector>
#include <algorithm>

struct Interval {
    int start, end;
};

// Function to find the maximum number of non-overlapping intervals
int maxNonOverlapping(std::vector<Interval>& intervals) {
    if (intervals.empty()) return 0;

    // Sort intervals based on their end times
    std::sort(intervals.begin(), intervals.end(), [](const Interval& a, const Interval& b) {
        return a.end < b.end;
    });

    int count = 1; // At least one interval can always be selected
    int lastEnd = intervals[0].end;

    // Iterate through sorted intervals and select non-overlapping ones
    for (int i = 1; i < intervals.size(); ++i) {
        if (intervals[i].start >= lastEnd) {
            count++;
            lastEnd = intervals[i].end;
        }
    }

    return count;
}

