// --- Patience Sorting Implementation ---

#include <vector>
#include <algorithm>
#include <iostream>

// Function to perform Patience Sorting
std::vector<int> patience_sort(const std::vector<int>& nums) {
    // --- build adjacency list ---
    std::vector<std::vector<int>> piles;
    for (int num : nums) {
        auto it = std::lower_bound(piles.begin(), piles.end(), num, [](const std::vector<int>& pile, int num) {
            return pile.back() < num;
        });
        if (it == piles.end()) {
            piles.push_back({num});
        } else {
            it->push_back(num);
        }
    }

    // --- build lis ---
    std::vector<int> lis;
    for (const auto& pile : piles) {
        lis.push_back(pile.back());
    }

    return lis;
}

