// --- Polynomial Hashing Implementation ---

// Time: O(n) for preprocessing, O(1) per query
// Space: O(n) for storing precomputed powers and hashes

#include <vector>
#include <string>
#include <numeric>
#include <algorithm>

using namespace std;
typedef long long ll;
const int MOD = 1e9 + 7;
const int P = 256;

// Precompute powers of P modulo MOD
vector<ll> precomputePowers(int n) {
    vector<ll> powers(n + 1);
    powers[0] = 1;
    for (int i = 1; i <= n; ++i) {
        powers[i] = (powers[i - 1] * P) % MOD;
    }
    return powers;
}

// Compute hash values for all prefixes of the string
vector<ll> computePrefixHashes(const string& s, const vector<ll>& powers) {
    int n = s.size();
    vector<ll> hashes(n + 1);
    for (int i = 0; i < n; ++i) {
        hashes[i + 1] = (hashes[i] + (s[i] - 'a' + 1) * powers[n - i - 1]) % MOD;
    }
    return hashes;
}

// Compute hash value for a substring s[l..r]
ll computeSubstringHash(const vector<ll>& hashes, int l, int r, const vector<ll>& powers) {
    ll hash = (hashes[r + 1] - hashes[l] * powers[r - l + 1]) % MOD;
    if (hash < 0) hash += MOD; // Handle negative results
    return hash;
}

