// --- Bézout's Identity & Linear Diophantine Solver ---

// Function to compute gcd and find coefficients x and y such that ax + by = gcd(a, b)
std::array<long long, 3> extended_gcd(long long a, long long b) {
    if (b == 0) {
        return {a, 1, 0}; // Base case: gcd(a, 0) = a, coefficients are (a, 0)
    }
    auto [gcd, x, y] = extended_gcd(b, a % b); // Recursive call
    return {gcd, y, x - (a / b) * y}; // Update coefficients
}

// Function to check if the equation ax + by = c has integer solutions
bool has_integer_solutions(long long a, long long b, long long c) {
    auto [gcd, _, _] = extended_gcd(a, b); // Compute gcd and coefficients
    return c % gcd == 0; // Check if c is divisible by gcd
}

// Function to find one particular solution (x₀, y₀) for ax + by = c
std::array<long long, 2> find_particular_solution(long long a, long long b, long long c) {
    auto [gcd, x, y] = extended_gcd(a, b); // Compute gcd and coefficients
    if (c % gcd != 0) {
        return {0, 0}; // No solution if c is not divisible by gcd
    }
    return {(c / gcd) * x, (c / gcd) * y}; // Scale the solution by c/gcd
}

// Function to find all solutions for ax + by = c
std::vector<std::array<long long, 2>> find_all_solutions(long long a, long long b, long long c) {
    auto [gcd, x₀, y₀] = extended_gcd(a, b); // Compute gcd and one particular solution
    if (c % gcd != 0) {
        return {}; // No solutions if c is not divisible by gcd
    }
    std::vector<std::array<long long, 2>> solutions;
    for (long long t = 0; t <= c / gcd; ++t) {
        solutions.push_back({x₀ + t * (b / gcd), y₀ - t * (a / gcd)}); // Generate all solutions
    }
    return solutions;
}

