    std::cout << "Particular solution: x₀ = " << x₀ << ", y₀ = " << y₀ << std::endl;

    // Find all solutions
    auto solutions = find_all_solutions(a, b, c);
    for (const auto& sol : solutions) {
        std::cout << "Solution: x = " << sol[0] << ", y = " << sol[1] << std::endl;
    }
} else {
    std::cout << "No integer solutions" << std::endl;
}

