// --- Time Complexity: O(n^2) ---
// --- Space Complexity: O(n) ---

#include <vector>

// Function to compute the nth Catalan number using dynamic programming
long long catalanNumber(int n) {
    // Initialize a vector to store the Catalan numbers up to n
    std::vector<long long> dp(n + 1, 0);
    dp[0] = 1; // Base case: C(0) = 1

    // Fill the dp array using the recursive formula
    for (int i = 1; i <= n; ++i) {
        for (int j = 0; j < i; ++j) {
            dp[i] += dp[j] * dp[i - 1 - j];
        }
    }

    return dp[n];
}

