// --- Chinese Remainder Theorem Implementation ---

// Time: O(n log M) — Space: O(n)

#include <vector>
#include <utility>
#include <numeric>

using ll = long long;
using pll = std::pair<ll, ll>;

// Extended Euclidean Algorithm to find the modular inverse
pll extended_gcd(ll a, ll b) {
    if (b == 0) return {1, 0};
    auto [x, y] = extended_gcd(b, a % b);
    return {y, x - a / b * y};
}

// Chinese Remainder Theorem to solve the system of congruences
ll chinese_remainder_theorem(const std::vector<ll>& remainders, const std::vector<ll>& moduli) {
    ll total = 0, prod = 1;
    for (size_t i = 0; i < moduli.size(); ++i) {
        prod *= moduli[i];
    }
    for (size_t i = 0; i < moduli.size(); ++i) {
        ll p = prod / moduli[i];
        auto [x, y] = extended_gcd(p, moduli[i]);
        total += remainders[i] * x * p;
    }
    return (total % prod + prod) % prod; // Ensure positive result
}

