// --- Precompute factorials and their modular inverses ---
vector<long long> fact, inv_fact;
void precompute(int n, int p) {
    fact.resize(n + 1), inv_fact.resize(n + 1);
    fact[0] = inv_fact[0] = 1;
    for (int i = 1; i <= n; ++i) {
        fact[i] = fact[i - 1] * i % p;
        inv_fact[i] = power(fact[i], p - 2, p); // Fermat's little theorem
    }
}

// --- Compute binomial coefficient using precomputed factorials ---
long long binomial(int n, int k, int p) {
    if (k > n) return 0;
    return fact[n] * inv_fact[k] % p * inv_fact[n - k] % p;
}

// --- Convert number to base-p representation ---
vector<int> to_base(int num, int p) {
    vector<int> res;
    while (num > 0) {
        res.push_back(num % p);
        num /= p;
    }
    reverse(res.begin(), res.end());
    return res;
}

// --- Compute binomial coefficient using Lucas' Theorem ---
long long lucas(int n, int k, int p) {
    if (k == 0) return 1;
    vector<int> n_base = to_base(n, p), k_base = to_base(k, p);
    long long res = 1;
    for (int i = 0; i < k_base.size(); ++i) {
        res *= binomial(n_base[i], k_base[i], p);
        res %= p;
    }
    return res;
}

