// --- FFT Implementation ---

#include <vector>
#include <complex>
#include <cmath>

using namespace std;
typedef complex<double> cpx;

// Time: O(n log n) — Space: O(n)
vector<cpx> fft(vector<cpx> &a, bool inverse = false) {
    int n = a.size();
    if (n == 1) return a;

    // --- build adjacency list ---
    vector<cpx> even, odd;
    for (int i = 0; i < n; ++i) {
        if (i % 2 == 0) even.push_back(a[i]);
        else odd.push_back(a[i]);
    }

    // --- recursive FFT calls ---
    vector<cpx> y_even = fft(even, inverse);
    vector<cpx> y_odd = fft(odd, inverse);

    // --- combine results using butterfly operations ---
    vector<cpx> y(n);
    double angle = 2 * M_PI / n;\    cpx w(1), wn(cos(angle), sin(angle));
    for (int k = 0; k < n / 2; ++k) {
        y[k] = y_even[k] + w * y_odd[k];
        y[k + n / 2] = y_even[k] - w * y_odd[k];
        if (inverse) {
            y[k] /= 2;
            y[k + n / 2] /= 2;
        }
        w *= wn;
    }

    return y;
}

