// --- Euler's Totient Function ---

// Time: O(n log log n) — Space: O(n)

#include <vector>
#include <cmath>

using namespace std;

vector<int> eulerTotient(int n) {
    vector<int> phi(n + 1);
    for (int i = 0; i <= n; ++i) phi[i] = i; // Initialize phi(i) to i

    // --- Sieve of Eratosthenes to compute phi(i) ---
    for (int p = 2; p <= n; ++p) {
        if (phi[p] == p) { // p is prime
            for (int i = p; i <= n; i += p) {
                phi[i] -= phi[i] / p; // Update phi(i) for multiples of p
            }
        }
    }

    return phi;
}

