// Function to calculate the number of elements in the union of multiple sets
long long inclusionExclusion(const std::vector<long long>& sizes, const std::vector<std::vector<long long>>& intersections) {
    long long n = sizes.size();
    long long result = 0;
    long long sign = 1;

    // --- iterate over all subsets of sets ---
    for (int i = 0; i < (1 << n); ++i) {
        long long subsetSize = 1;
        long long intersectionSize = 1;

        // --- calculate the size of the current subset and its intersection ---
        for (int j = 0; j < n; ++j) {
            if (i & (1 << j)) {
                subsetSize *= sizes[j];
                intersectionSize *= intersections[j][j];
            }
        }

        // --- apply inclusion-exclusion principle ---
        result += sign * (subsetSize - intersectionSize);
        sign *= -1;
    }

    return result;
}

