// --- Gaussian elimination over GF(2) ---

#include <vector>
#include <algorithm>

// Function to perform Gaussian elimination over GF(2)
std::vector<int> gaussianEliminationGF2(const std::vector<std::vector<int>>& matrix) {
    int n = matrix.size();
    std::vector<std::vector<int>> augmentedMatrix = matrix;

    // --- Forward elimination ---
    for (int i = 0; i < n; ++i) {
        // Find a pivot in the current column
        int pivotRow = i;
        for (int j = i + 1; j < n; ++j) {
            if (augmentedMatrix[j][i] == 1) {
                pivotRow = j;
                break;
            }
        }

        // Swap rows to bring the pivot to the current position
        std::swap(augmentedMatrix[i], augmentedMatrix[pivotRow]);

        // Eliminate the current column below the pivot
        for (int j = i + 1; j < n; ++j) {
            if (augmentedMatrix[j][i] == 1) {
                for (int k = i; k <= n; ++k) {
                    augmentedMatrix[j][k] ^= augmentedMatrix[i][k];
                }
            }
        }
    }

    // --- Back substitution ---
    std::vector<int> solution(n, 0);
    for (int i = n - 1; i >= 0; --i) {
        int pivot = augmentedMatrix[i][i];
        if (pivot == 0) {
            // The system is inconsistent
            return {};
        }
        solution[i] = augmentedMatrix[i][n] % 2;
        for (int j = i - 1; j >= 0; --j) {
            augmentedMatrix[j][n] ^= solution[i] * augmentedMatrix[j][i];
        }
    }

    return solution;
}

