// --- Space Complexity: O(n) for storing the recurrence relation ---

#include <vector>
#include <array>
#include <iostream>

using namespace std;
typedef long long ll;

// Function to multiply two matrices
array<array<ll, 2>, 2> multiply(const array<array<ll, 2>, 2>& a, const array<array<ll, 2>, 2>& b) {
    array<array<ll, 2>, 2> result = {{{0, 0}, {0, 0}}};
    for (int i = 0; i < 2; ++i) {
        for (int j = 0; j < 2; ++j) {
            for (int k = 0; k < 2; ++k) {
                result[i][j] += a[i][k] * b[k][j];
            }
        }
    }
    return result;
}

// Function to perform matrix exponentiation
array<array<ll, 2>, 2> matrixPower(const array<array<ll, 2>, 2>& base, int exp) {
    array<array<ll, 2>, 2> result = {{{1, 0}, {0, 1}}}; // Identity matrix
    array<array<ll, 2>, 2> current = base;
    while (exp > 0) {
        if (exp % 2 == 1) {
            result = multiply(result, current);
        }
        current = multiply(current, current);
        exp /= 2;
    }
    return result;
}

// Function to compute the nth Fibonacci number using matrix exponentiation
ll fibonacci(int n) {
    if (n <= 1) return n;
    array<array<ll, 2>, 2> base = {{{1, 1}, {1, 0}}};
    array<array<ll, 2>, 2> result = matrixPower(base, n - 1);
    return result[0][0];
}

