// --- Linear Sieve ---

#include <vector>
#include <cmath>

// Time: O(n log log n) — Space: O(n)
std::vector<bool> linear_sieve(int n) {
    std::vector<bool> is_prime(n + 1, true);
    is_prime[0] = is_prime[1] = false;

    for (int p = 2; p <= n; ++p) {
        if (is_prime[p]) {
            // Mark multiples of p starting from p^2
            for (int i = p * p; i <= n; i += p) {
                is_prime[i] = false;
            }
        }
    }

    return is_prime;
}

