// --- Lucas' Theorem Implementation ---

// Function to compute binomial coefficient modulo p using dynamic programming
long long binom_mod_p(long long n, long long k, long long p) {
    // Initialize a DP table with dimensions (n+1) x (k+1)
    vector<vector<long long>> dp(n + 1, vector<long long>(k + 1, 0));

    // Base case: binom(n, 0) = 1 for all n
    for (long long i = 0; i <= n; ++i) {
        dp[i][0] = 1;
    }

    // Fill the DP table using the recurrence relation
    for (long long i = 1; i <= n; ++i) {
        for (long long j = 1; j <= k && j <= i; ++j) {
            dp[i][j] = (dp[i - 1][j] + dp[i - 1][j - 1]) % p;
        }
    }

    // Return the computed binomial coefficient modulo p
    return dp[n][k];
}

// Function to compute Lucas' Theorem for binomial coefficient modulo p
long long lucas_theorem(long long n, long long k, long long p) {
    if (k == 0) return 1; // Base case: binom(n, 0) = 1

    // Extract the least significant digits of n and k in base p
    long long n_last_digit = n % p;
    long long k_last_digit = k % p;

    // Recursively compute the product of binomial coefficients modulo p
    return (binom_mod_p(n_last_digit, k_last_digit, p) * lucas_theorem(n / p, k / p, p)) % p;
}

// --- Usage Example ---

// Read input values
long long n, k, p;
cin >> n >> k >> p;

// Compute the result using Lucas' Theorem
