// --- Matrix Exponentiation ---

// Function to multiply two matrices
vector<vector<long long>> multiply(const vector<vector<long long>>& A, const vector<vector<long long>>& B) {
    int n = A.size(); // Number of rows in A
    int m = B[0].size(); // Number of columns in B
    int p = B.size(); // Number of columns in A
    vector<vector<long long>> C(n, vector<long long>(m, 0));
    for (int i = 0; i < n; ++i) {
        for (int j = 0; j < m; ++j) {
            for (int k = 0; k < p; ++k) {
                C[i][j] += A[i][k] * B[k][j]; // Matrix multiplication
            }
        }
    }
    return C;
}

// Function to perform matrix exponentiation using binary exponentiation
vector<vector<long long>> matrixExponentiation(const vector<vector<long long>>& M, int n) {
    int size = M.size(); // Size of the square matrix
    vector<vector<long long>> result(size, vector<long long>(size, 0));
    for (int i = 0; i < size; ++i) {
        result[i][i] = 1; // Identity matrix initialization
    }
    vector<vector<long long>> base = M; // Base matrix
    while (n > 0) {
        if (n % 2 == 1) {
            result = multiply(result, base); // Multiply if n is odd
        }
        base = multiply(base, base); // Square the base
        n /= 2; // Halve n
    }
    return result;
}

// Function to compute the nth Fibonacci number using matrix exponentiation
long long fibonacci(int n) {
    if (n <= 1) return n; // Base cases for F(0) and F(1)
    vector<vector<long long>> M = {{1, 1}, {1, 0}}; // Transformation matrix
    vector<vector<long long>> result = matrixExponentiation(M, n - 1); // Compute M^(n-1)
    return result[0][0]; // Top-left element of the result matrix is F(n)
}

