// --- build linear basis ---
std::vector<long long> buildXORBasis(const std::vector<long long>& nums) {
    std::vector<long long> basis;
    for (long long num : nums) {
        // --- reduce num using existing basis ---
        for (int i = 0; i < basis.size(); ++i) {
            if (num & basis[i]) {
                num ^= basis[i]; // eliminate higher bits first
            }
        }
        // --- add new basis vector if non-zero ---
        if (num != 0) {
            basis.push_back(num);
        }
    }
    return basis;
}

// --- find maximum XOR using basis ---
long long maxXOR(const std::vector<long long>& basis, long long num) {
    long long max_xor = 0;
    for (int i = 31; i >= 0; --i) {
        if (num & (1LL << i)) {
            max_xor |= (1LL << i);
        } else {
            for (long long b : basis) {
                if (b & (1LL << i)) {
                    num ^= b;
                    max_xor |= (1LL << i);
                    break;
                }
            }
        }
    }
    return max_xor;
}

