// Function to perform interactive binary search
int interactiveBinarySearch(int n) {
    int low = 0, high = n - 1;
    while (low <= high) {
        int mid = low + (high - low) / 2;
        cout << mid << endl; // Send guess to the judge
        string feedback;
        cin >> feedback; // Receive feedback from the judge
        if (feedback == "higher") {
            high = mid - 1;
        } else if (feedback == "lower") {
            low = mid + 1;
        } else {
            return mid; // Found the target
        }
    }
    return -1; // Target not found
}

