// --- Time Complexity: O(2^(n/2) + 2^(n/2) * log(2^(n/2))) = O(2^n)
// --- Space Complexity: O(2^(n/2))

#include <vector>
#include <unordered_set>
#include <algorithm>

using namespace std;

// Function to find if there exists a subset with sum equal to target
bool meetInMiddle(const vector<int>& nums, int target) {
    int n = nums.size();
    int half = n / 2;

    // Generate all subset sums for the first half
    unordered_set<int> leftSums;
    for (int i = 0; i < (1 << half); ++i) {
        int sum = 0;
        for (int j = 0; j < half; ++j) {
            if (i & (1 << j)) {
                sum += nums[j];
            }
        }
        leftSums.insert(sum);
    }

    // Generate all subset sums for the second half and check if complement exists in leftSums
    for (int i = 0; i < (1 << (n - half)); ++i) {
        int sum = 0;
        for (int j = half; j < n; ++j) {
            if (i & (1 << (j - half))) {
                sum += nums[j];
            }
        }
        if (leftSums.count(target - sum)) {
            return true;
        }
    }

    return false;
}

