// --- sweep-line algorithm for offline processing ---

#include <vector>
#include <algorithm>
#include <iostream>

using namespace std;

struct Event {
    int x;
    char type; // 'A' for add, 'R' for remove
    char id;
};

// --- build events from input ---
vector<Event> buildEvents(const vector<pair<int, char>>& points) {
    vector<Event> events;
    for (int i = 0; i < points.size(); ++i) {
        events.push_back({points[i].first, 'A', points[i].second});
        events.push_back({points[i].first, 'R', points[i].second});
    }
    return events;
}

// --- sort events by x-coordinate ---
void sortEvents(vector<Event>& events) {
    sort(events.begin(), events.end(), [](const Event& a, const Event& b) {
        return a.x < b.x || (a.x == b.x && a.type < b.type);
    });
}

// --- process events using sweep-line algorithm ---
vector<char> processEvents(const vector<Event>& events) {
    vector<char> result;
    map<char, int> active;
    for (const auto& event : events) {
        if (event.type == 'A') {
            if (active.find(event.id) == active.end()) {
                active[event.id] = 1;
                result.push_back(event.id);
            }
        } else {
            if (active.find(event.id) != active.end()) {
                active.erase(event.id);
                if (active.empty()) {
                    result.push_back('E'); // End of processing
                }
            }
        }
    }
    return result;
}

// --- main function for demonstration purposes ---
int main() {
    vector<pair<int, char>> points = {{3, 'A'}, {1, 'B'}, {4, 'C'}, {2, 'D'}};
    auto events = buildEvents(points);
    sortEvents(events);
    auto result = processEvents(events);
    for (char c : result) {
        cout << c << " ";
    }
    return 0;
}

