// --- Randomized Duplicate Finder ---

#include <vector>
#include <unordered_set>
#include <random>
#include <ctime>

// Function to find a duplicate in an array using a randomized approach
int findDuplicate(const std::vector<int>& nums) {
    // Initialize random number generator
    std::mt19937 gen(std::time(0));
    std::uniform_int_distribution<> dis(0, nums.size() - 1);

    // Use an unordered set to track seen elements
    std::unordered_set<int> seen;

    // --- build adjacency list ---
    while (true) {
        int index = dis(gen); // Randomly select an index
        if (seen.find(nums[index]) != seen.end()) {
            return nums[index]; // Duplicate found
        }
        seen.insert(nums[index]); // Mark element as seen
    }
}

