// --- Floyd-Warshall Algorithm ---

// Time: O(V^3) — Space: O(V^2)

#include <vector>
#include <climits>

using namespace std;

// Function to perform Floyd-Warshall algorithm
void floydWarshall(vector<vector<long long>>& dist, int V) {
    // --- build adjacency list ---
    // Initialize the distance matrix with given values and infinity for non-edges
    for (int i = 0; i < V; ++i) {
        for (int j = 0; j < V; ++j) {
            if (i == j)
                dist[i][j] = 0;
            else if (dist[i][j] == INT_MAX)
                dist[i][j] = LLONG_MAX; // Use long long to handle large distances
        }
    }

    // --- Floyd-Warshall algorithm ---
    // Iterate over all vertices as intermediate points
    for (int k = 0; k < V; ++k) {
        for (int i = 0; i < V; ++i) {
            for (int j = 0; j < V; ++j) {
                // Update the distance if a shorter path is found
                dist[i][j] = min(dist[i][j], dist[i][k] + dist[k][j]);
            }
        }
    }
}

