// --- build adjacency list ---
std::vector<std::pair<int, long long>> adj[N]; // adjacency list for the graph

// --- topological sort using Kahn's algorithm ---
std::queue<int> q;
std::vector<long long> in_degree(N, 0);
for (int u = 0; u < N; ++u) {
    for (auto [v, w] : adj[u]) {
        ++in_degree[v]; // count incoming edges
    }
}
for (int u = 0; u < N; ++u) {
    if (in_degree[u] == 0) {
        q.push(u); // start with nodes having no incoming edges
    }
}

// --- dynamic programming to find longest path ---
std::vector<long long> dp(N, 0);
while (!q.empty()) {
    int u = q.front();
    q.pop();
    for (auto [v, w] : adj[u]) {
        dp[v] = std::max(dp[v], dp[u] + w); // update longest path to v
        if (--in_degree[v] == 0) {
            q.push(v); // add node v to queue if all its predecessors are processed
        }
    }
}

// --- find the maximum path length ---
long long max_path = 0;
for (int u = 0; u < N; ++u) {
    max_path = std::max(max_path, dp[u]); // update max path found
}

return max_path;

