struct Edge {
    int to;
    long long weight;
};

using Graph = vector<vector<Edge>>;

// --- SPFA with SLF optimization ---
vector<long long> spfa(const Graph& graph, int source) {
    int n = graph.size();
    vector<long long> dist(n, LLONG_MAX);
    dist[source] = 0;
    queue<int> q;
    q.push(source);
    vector<bool> in_queue(n, false);
    in_queue[source] = true;

    while (!q.empty()) {
        int u = q.front();
        q.pop();
        in_queue[u] = false;

        for (const auto& edge : graph[u]) {
            int v = edge.to;
            long long weight = edge.weight;

            if (dist[u] + weight < dist[v]) {
                dist[v] = dist[u] + weight;
                if (!in_queue[v]) {
                    q.push(v);
                    in_queue[v] = true;
                }
            }
        }
    }

    return dist;
}

