// --- build adjacency list ---
std::vector<std::vector<int>> build_adjacency_list(const std::vector<std::vector<int>>& matrix) {
    int n = matrix.size();
    std::vector<std::vector<int>> adj(n, std::vector<int>(n, 0));
    for (int i = 0; i < n; ++i) {
        for (int j = 0; j < n; ++j) {
            if (matrix[i][j] == 1) {
                adj[i][j] = 1;
            }
        }
    }
    return adj;
}

// --- transitive closure using Floyd-Warshall algorithm ---
std::vector<std::vector<int>> floyd_warshall(const std::vector<std::vector<int>>& adj) {
    int n = adj.size();
    std::vector<std::vector<int>> dist = adj;
    for (int k = 0; k < n; ++k) {
        for (int i = 0; i < n; ++i) {
            for (int j = 0; j < n; ++j) {
                dist[i][j] = dist[i][j] || (dist[i][k] && dist[k][j]);
            }
        }
    }
    return dist;
}

// --- usage example ---
int main() {
    std::vector<std::vector<int>> matrix = {{0, 1, 0}, {0, 0, 1}, {1, 0, 0}};
    auto adj = build_adjacency_list(matrix);
    auto transitive_closure = floyd_warshall(adj);
    // Output the transitive closure matrix
    for (const auto& row : transitive_closure) {
        for (int val : row) {
            std::cout << val << " ";
        }
        std::cout << std::endl;
    }
    return 0;
}

